"""Random arrays for sum_array: a count, then that many values.

Values are kept small enough that the total cannot come near overflowing a
32-bit int, so the expected output is a fact about the arithmetic rather than
about wrap-around.
"""

LOW, HIGH = -500, 500


def generate(rng, count):
    builders = (_mixed, _all_positive, _all_negative, _single)
    return [builders[i % len(builders)](rng, i + 1) for i in range(count)]


def _case(name, values, description=""):
    return {
        "name": name,
        "stdin": "%d\n%s\n" % (len(values),
                                " ".join(str(v) for v in values)),
        "description": description,
    }


def _mixed(rng, index):
    values = [rng.randint(LOW, HIGH) for _ in range(rng.randint(4, 15))]
    return _case("mixed signs #%d" % index, values)


def _all_positive(rng, index):
    values = [rng.randint(1, HIGH) for _ in range(rng.randint(4, 15))]
    return _case("all positive #%d" % index, values)


def _all_negative(rng, index):
    values = [rng.randint(LOW, -1) for _ in range(rng.randint(4, 15))]
    return _case("all negative #%d" % index, values)


def _single(rng, index):
    return _case("one element #%d" % index, [rng.randint(LOW, HIGH)],
                 "The loop must run exactly once, not zero times and not "
                 "twice.")
